    "bpomClassification": "Obat Keras",
    "drugClassification": "💊 Obat Keras (Injeksi IV Infus ICU / High Alert Medication)",
    "description": "Katekolamin simpatomimetik poten yang bekerja langsung menstimulasi reseptor alfa-1 adrenergik vaskular (vasokonstriksi perifer kuat) dan beta-1 kardiak (inotropik/kronotropik positif moderat), merupakan vasopresor lini pertama pilihan utama untuk syok septik dan syok distributif.",
    "indication": "1. Syok Septik & Syok Distributif (Vasopresor Lini Pertama - Surviving Sepsis Campaign).\n2. Syok Kardiogenik dengan Hipotensi Ekstrem (MAP < 65 mmHg) bersama inotropik.\n3. Hipotensi Akut Mengancam Jiwa yang tidak responsif terhadap resusitasi cairan adekuat.\n4. Pemulihan Tekanan Darah Pasca-Henti Jantung (ROSC Hemodynamic Support).",
    "offLabelIndication": "• Hipotensi Refrakter Terinduksi Anestesi Spinal/Epidural Obstetri: Infus mikro 0.02 - 0.05 mcg/kg/menit.\n• Syok pada Emboli Paru Masif / Gagal Jantung Kanan Akut.",
    "dosage": "• Syok Septik / Hipotensi Akut Dewasa: Awal 0.02 - 0.05 mcg/kg/menit (atau 2-4 mcg/menit) IV via syringe pump, titrasi cepat tiap 2-5 menit hingga target MAP >= 65 mmHg. Dosis rumatan umum 0.05 - 0.5 mcg/kg/menit (pada syok refrakter dapat mencapai 1.0 - 3.0 mcg/kg/menit).\n• Pasca-Henti Jantung (ROSC): 0.1 - 0.5 mcg/kg/menit IV kontinu.",
    "adultDosage": "• Syok Septik: 0.02 - 1.0 mcg/kg/menit IV infus kontinu dititrasi target MAP >= 65 mmHg.",
    "pediatricDosage": "• Syok Septik Pediatrik: 0.05 - 0.1 mcg/kg/menit IV kontinu, titrasi bertahap hingga target tekanan darah perfusi normal sesuai usia (maksimal 1.0 - 2.0 mcg/kg/menit).",
    "geriatricDosage": "Gunakan titrasi bertahap dan pemantauan perfusi perifer ketat; pasien lansia lebih rentan terhadap iskemia miokard dan aritmia ventrikel.",
    "renalDoseAdjustment": "Tidak memerlukan penyesuaian dosis; namun vasokonstriksi dosis tinggi dapat memperburuk iskemia ginjal bila cairan intravaskular belum terisi adekuat.",
    "hepaticDoseAdjustment": "Tidak memerlukan penyesuaian dosis.",
    "maxDoseLimit": "Tidak ada batas dosis mutlak; pada syok septik refrakter dosis dapat dititrasi hingga > 1.0 - 3.0 mcg/kg/menit bersama penambahan vasopresor lini kedua (Vasopressin / Epinefrin).",
    "administrationGuideline": "• HARUS DIBERIKAN MELALUI KATETER VENA SENTRAL (CVC) menggunakan syringe pump / infusion pump terkalibrasi presisi.\n• Sediaan pekat 1 mg/mL HARUS diencerkan dalam D5W atau D5NS (4 mg dalam 50 mL D5W = 80 mcg/mL); jangan dilarutkan dalam NaCl 0.9% murni tanpa dekstrosa karena potensi oksidasi katekolamin.\n• PROTOKOL EKSTRAVASASI: Jika terjadi ekstravasasi ke jaringan subkutan, SEGERA infiltrasi area terdampak dengan Phentolamine 5 - 10 mg dalam 10-15 mL NaCl 0.9% menggunakan jarum halus untuk membalikkan vasokonstriksi lokal dan mencegah nekrosis gangren.",
    "contraindications": "Hipotensi sekunder akibat hipovolemia berat yang belum terkoreksi (kecuali sebagai tindakan darurat sementara sebelum volume intravaskular terisi); Trombosis vaskular perifer atau mesenterika akut; Hipersensitivitas terhadap bisulfit (pengawet).",
    "sideEffects": "Iskemia perifer (ujung jari dingin/pucat), bradikardia refleks (akibat lonjakan tekanan darah), takikardia, kecemasan, sakit kepala berdenyut, diaphoresis.",
    "adverseEffects": "Iskemia dan Gangren Jaringan Perifer Akut (Digital Necrosis / Blue Toe Syndrome), Aritmia Kardiak (Takikardia Ventrikel / Fibrilasi Atrium), Nekrosis Jaringan Parah akibat Ekstravasasi, Iskemia Miokard Akut / Peningkatan Kebutuhan Oksigen Jantung, Iskemia Usus / Nekrosis Mesenterika.",
    "pharmacology": "Agonis kuat reseptor alfa-1 adrenergik (meningkatkan resistensi vaskular sistemik / SVR dan tekanan darah arteri secara nyata tanpa penurunan curah jantung signifikan) dan stimulator moderat reseptor beta-1 kardiak (meningkatkan kontraktilitas inotropik miokardium). Efek beta-2 vasodilatasi minimal.",
    "foodInteraction": "Pemberian infus intravena kontinu sentral.",
    "pregnancyCategory": "C (Gunakan untuk penyelamatan hidup pada syok maternal; pertimbangkan potensi vasokonstriksi arteri uterina).",
    "halfLife": "1 - 2 menit (durasi kerja berakhir 1-2 menit setelah infus dihentikan)",
    "clearance": "Metabolisme seluler cepat via enzim COMT (Catechol-O-Methyltransferase) dan MAO (Monoamine Oxidase) di hepar, ginjal, dan jaringan; ekskresi metabolit inaktif via urin.",
    "ddinterId": "DDInter-D00047",
    "blackBoxWarning": "PERINGATAN EKSTRAVASASI & NEKROSIS GANGREN: Ekstravasasi norepinefrin ke jaringan subkutan perifer memicu vasokonstriksi hebat dan nekrosis gangren jaringan lokal. Berikan HANYA melalui vena sentral (CVC). Jika terjadi ekstravasasi, SEGERA lakukan infiltrasi lokal dengan Antidotum PHENTOLAMINE (5-10 mg dalam 10 mL NS).\nPERINGATAN HIPERVOLEMIA: Pastikan status volume intravaskular terhidrasi adekuat sebelum atau bersamaan dengan inisiasi vasopresor.",
    "lactationWarning": "Waktu paruh sangat singkat (<2 menit); tidak mencapai ASI dalam jumlah bermakna.",
    "cypPathway": "Degradasi enzimatik oleh COMT dan MAO (bukan via sitokrom CYP450).",
    "monitoringParameters": "Mean Arterial Pressure (MAP - target >= 65 mmHg, continuous Arterial Line), Laktat serum serial (klirens laktat menandakan perbaikan perfusi), Produksi urin per jam (kateter urin, target >0.5 mL/kg/jam), Kepatenan kateter CVC dan perfusi akral ekstremitas (suhu, CRT, denyut nadi perifer), Rekam EKG kontinu (aritmia).",
    "patientTips": "Obat darurat ICU: Pasien dan keluarga akan diinformasikan bahwa obat ini diberikan terus menerus melalui infus kateter khusus untuk menjaga tekanan darah dan aliran darah ke organ-organ vital.",
    "drugsComUrl": "https://www.drugs.com/monograph/norepinephrine.html",
